/** Set by the build from package.json. */
declare const __APP_VERSION__: string;
/** The phone app's website (GitHub Pages) and the Android app download, from electron-builder.yml. */
declare const __PAGES_URL__: string;
declare const __APK_URL__: string;
declare const __REPO__: string;
/** CSS files imported for their styles (Vite bundles them). */
declare module '*.css';
